// src/i18n.ts
var i18n_default = instance;
async function initializeI18n() {
  await instance.init({
    lng: process.env.BOT_LANGUAGE || "ru",
    fallbackLng: "en",
    debug: process.env.DEV_MODE === "true",
    resources: {
      en: {
        translation: en_default
      },
      ru: {
        translation: ru_default
      }
    },
    interpolation: {
      escapeValue: false
    }
  });
}

// src/services/notification-service/notification.service.ts
class NotificationService {
  static getChatDisplayName(chat) {
    if (chat.title) {
      return chat.title;
    }
    if (chat.type === "private") {
      const firstName = chat.first_name || "";
      const lastName = chat.last_name || "";
      return `${firstName} ${lastName}`.trim() || chat.username || i18n_default.t("common.private_chat");
    }
    return chat.username || i18n_default.t("common.unknown_chat");
  }
  static getUserDisplayName(user) {
    const firstName = user.first_name || "";
    const lastName = user.last_name || "";
    return `${firstName} ${lastName}`.trim() || user.username || i18n_default.t("common.unknown_user");
  }
  static escapeMarkdown(text) {
    if (!text)
      return "";
    const toEscape = /[_*[\]()~`>#+\-=|{}.!]/g;
    return text.replace(toEscape, "\\$&");
  }
  static escapeForCode(text) {
    if (!text)
      return "";
    return text.replace(/`/g, "\\`").replace(/\\/g, "\\\\");
  }
  static formatCacheMissNotification(chatName, messageIds) {
    const idsText = messageIds.length === 1 ? `ID ${messageIds[0]}` : `IDs: ${messageIds.join(", ")}`;
    return i18n_default.t("notifications.original_not_found", {
      chatName: this.escapeMarkdown(chatName),
      messageId: idsText
    });
  }
  static escapeMarkdownStatic(text) {
    return this.escapeMarkdown(text);
  }
}

// src/handlers/messageEditHandler.ts
class MessageEditHandler {
  cacheService;
  ownerId;
  telegramService;
  logger = Logger.getInstance();
  constructor(cacheService, ownerId, telegramService) {
    this.cacheService = cacheService;
    this.ownerId = ownerId;
    this.telegramService = telegramService;
  }
  async handleEditedBusinessMessage(ctx) {
    try {
      const update = ctx.update;
      if (!update.edited_business_message) {
        return;
      }
      const editedMessage = update.edited_business_message;
      await this.handleEditedMessage(ctx, editedMessage);
    } catch (error) {
      this.logger.error("\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u0438 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0435 \u043E\u0442\u0440\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0433\u043E \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F:", error);
    }
  }
  async handleEditedMessage(ctx, editedMessage) {
    this.logger.info(`\u041E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F ID: ${editedMessage.message_id}`);
    const originalMessage = await this.cacheService.getCachedMessage(editedMessage.business_connection_id, editedMessage.chat.id, editedMessage.message_id);
    if (!originalMessage) {
      this.logger.warn(`\u041E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u044C\u043D\u043E\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E \u0432 \u043A\u044D\u0448\u0435 \u0434\u043B\u044F ID: ${editedMessage.message_id}`);
      const chatName2 = NotificationService.getChatDisplayName(editedMessage.chat);
      const notification = NotificationService.formatCacheMissNotification(chatName2, [editedMessage.message_id]);
      await ctx.telegram.sendMessage(this.ownerId, notification, {
        parse_mode: "MarkdownV2"
      });
      return;
    }
    const oldText = originalMessage.text || "";
    const newText = editedMessage.text || "";
    if (oldText === newText) {
      this.logger.info(`\u0422\u0435\u043A\u0441\u0442 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F ${editedMessage.message_id} \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u0441\u044F, \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u043C`);
      return;
    }
    if (originalMessage.s3Key) {
      this.cacheService.setValue(`${this.ownerId}:latest_media_key`, originalMessage.s3Key, 120);
    }
    const userName = editedMessage.from ? NotificationService.getUserDisplayName(editedMessage.from) : i18n_default.t("common.unknown_user");
    const chatName = NotificationService.getChatDisplayName(editedMessage.chat);
    const userUsername = editedMessage.from?.username;
    const usernameLine = userUsername ? `
\uD83D\uDC64 \`${NotificationService.escapeForCode(userUsername)}\`` : "";
    const contextNotification = i18n_default.t("notifications.edited", {
      userName: NotificationService.escapeMarkdown(userName),
      chatName: NotificationService.escapeMarkdown(chatName),
      usernameLine
    });
    await ctx.telegram.sendMessage(this.ownerId, contextNotification, {
      parse_mode: "MarkdownV2",
      link_preview_options: { is_disabled: true }
    });
    const beforeCaption = `${i18n_default.t("common.before")}
${oldText || i18n_default.t("common.message_without_text")}`;
    await this.telegramService.sendContentMessage(this.ownerId, beforeCaption, originalMessage.s3Key);
    const afterTextContent = newText || (originalMessage.s3Key ? "" : i18n_default.t("common.message_without_text"));
    const afterCaption = `${i18n_default.t("common.after")}
${afterTextContent}`;
    await this.telegramService.sendContentMessage(this.ownerId, afterCaption, originalMessage.s3Key);
    const newCachedMessage = {
      ...originalMessage,
      ...editedMessage,
      text: newText,
      s3Key: originalMessage.s3Key ?? null
    };
    await this.cacheService.cacheMessage(newCachedMessage);
    this.logger.info(`\u0423\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u043E\u0431 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0438 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043E \u0434\u043B\u044F \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F ID: ${editedMessage.message_id}`);
  }
}

// src/handlers/messageDeleteHandler.ts
class MessageDeleteHandler {
  cacheService;
  ownerId;
  telegramService;
  s3Service;
  logger = Logger.getInstance();
  constructor(cacheService, ownerId, telegramService, s3Service) {
    this.cacheService = cacheService;
    this.ownerId = ownerId;
    this.telegramService = telegramService;
    this.s3Service = s3Service;
  }
  async handleDeletedBusinessMessages(ctx) {
    const update = ctx.update;
    if (!("deleted_business_messages" in update))
      return;
    const deletedMessages = update.deleted_business_messages;
    this.logger.info(`\u041E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D\u043E \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435 ${deletedMessages.message_ids.length} \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0439 \u0432 \u0447\u0430\u0442\u0435 ID: ${deletedMessages.chat.id}`);
    await this.processDeletedMessages(ctx, deletedMessages);
  }
  async processDeletedMessages(ctx, deletedMessages) {
    const chatName = NotificationService.getChatDisplayName(deletedMessages.chat);
    const cachedMessages = await this.cacheService.getCachedMessages(deletedMessages.business_connection_id, deletedMessages.chat.id, deletedMessages.message_ids);
    const foundMessages = [];
    const missedMessageIds = [];
    for (const messageId of deletedMessages.message_ids) {
      const cached = cachedMessages.find((msg) => msg.message_id === messageId);
      cached ? foundMessages.push(cached) : missedMessageIds.push(messageId);
    }
    if (foundMessages.length > 0) {
      await this.sendDeleteNotifications(ctx, foundMessages, chatName);
    }
    if (missedMessageIds.length > 0) {
      const notification = NotificationService.formatCacheMissNotification(chatName, missedMessageIds);
      await ctx.telegram.sendMessage(this.ownerId, notification, {
        parse_mode: "MarkdownV2"
      });
    }
    for (const messageId of deletedMessages.message_ids) {
      await this.cacheService.removeCachedMessage(deletedMessages.business_connection_id, deletedMessages.chat.id, messageId);
    }
  }
  async sendDeleteNotifications(ctx, deletedMessages, chatName) {
    const messagesByUser = new Map;
    for (const message of deletedMessages) {
      const userId = message.from?.id.toString() || "unknown";
      if (!messagesByUser.has(userId)) {
        messagesByUser.set(userId, []);
      }
      messagesByUser.get(userId).push(message);
    }
    for (const userMessages of messagesByUser.values()) {
      if (userMessages.length === 0)
        continue;
      const firstMessage = userMessages[0];
      if (!firstMessage)
        continue;
      const userName = firstMessage.from ? NotificationService.getUserDisplayName(firstMessage.from) : i18n_default.t("common.unknown_user");
      const userUsername = firstMessage.from?.username;
      const usernameLine = userUsername ? `
\uD83D\uDC64 \`${NotificationService.escapeForCode(userUsername)}\`` : "";
      if (userMessages.length === 1) {
        const message = userMessages[0];
        if (!message)
          continue;
        const contextNotification = i18n_default.t("notifications.deleted", {
          userName: NotificationService.escapeMarkdown(userName),
          chatName: NotificationService.escapeMarkdown(chatName),
          usernameLine
        });
        await ctx.telegram.sendMessage(this.ownerId, contextNotification, {
          parse_mode: "MarkdownV2",
          link_preview_options: { is_disabled: true }
        });
        if (message.s3Key) {
          this.cacheService.setValue(`${this.ownerId}:latest_media_key`, message.s3Key, 120);
        }
        const deletedCaption = `${i18n_default.t("common.deleted")}
${message.text || i18n_default.t("common.message_without_text")}`;
        await this.telegramService.sendContentMessage(this.ownerId, deletedCaption, message.s3Key);
      } else {
        const contextNotification = i18n_default.t("notifications.deleted_multiple", {
          userName: NotificationService.escapeMarkdown(userName),
          chatName: NotificationService.escapeMarkdown(chatName),
          usernameLine,
          count: userMessages.length
        });
        await ctx.telegram.sendMessage(this.ownerId, contextNotification, {
          parse_mode: "MarkdownV2",
          link_preview_options: { is_disabled: true }
        });
        for (let i = 0;i < userMessages.length; i++) {
          const message = userMessages[i];
          if (!message)
            continue;
          const deletedCaption = `${i18n_default.t("common.deleted_item", {
            index: i + 1
          })}
${message.text || i18n_default.t("common.message_without_text")}`;
          if (message.s3Key) {
            this.cacheService.setValue(`${this.ownerId}:latest_media_key`, message.s3Key, 120);
          }
          await this.telegramService.sendContentMessage(this.ownerId, deletedCaption, message.s3Key);
        }
      }
    }
  }
}

