// src/services/subscription-service/subscription.service.ts
class SubscriptionService {
  logger = Logger.getInstance();
  prisma;
  constructor() {
    this.prisma = PrismaService.getInstance();
  }
  async findOrCreateUser(telegramId) {
    const user = await this.prisma.user.findUnique({
      where: { telegramId }
    });
    if (user) {
      return user;
    }
    this.logger.info(`\u0421\u043E\u0437\u0434\u0430\u0435\u043C \u043D\u043E\u0432\u043E\u0433\u043E \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u0441 Telegram ID: ${telegramId}`);
    return this.prisma.user.create({
      data: {
        telegramId,
        subscriptionStatus: "FREE"
      }
    });
  }
  async getUserSubscriptionStatus(telegramId) {
    const user = await this.findOrCreateUser(telegramId);
    if (user.subscriptionStatus === "PREMIUM" && user.subscriptionEndsAt && user.subscriptionEndsAt.getTime() < Date.now()) {
      this.logger.info(`\u041F\u043E\u0434\u043F\u0438\u0441\u043A\u0430 \u0434\u043B\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F ${telegramId} \u0438\u0441\u0442\u0435\u043A\u043B\u0430. \u041C\u0435\u043D\u044F\u0435\u043C \u0441\u0442\u0430\u0442\u0443\u0441 \u043D\u0430 FREE.`);
      await this.prisma.user.update({
        where: { telegramId },
        data: { subscriptionStatus: "FREE", subscriptionEndsAt: null }
      });
      return "FREE";
    }
    return user.subscriptionStatus;
  }
  async setUserSubscriptionStatus(telegramId, status, expiresAtISO) {
    await this.findOrCreateUser(telegramId);
    const expiresAt = expiresAtISO ? new Date(expiresAtISO) : null;
    await this.prisma.user.update({
      where: { telegramId },
      data: {
        subscriptionStatus: status,
        subscriptionEndsAt: expiresAt
      }
    });
    this.logger.info(`\u0421\u0442\u0430\u0442\u0443\u0441 \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0438 \u0434\u043B\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F ${telegramId} \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D \u043D\u0430 ${status}. \u0421\u0440\u043E\u043A \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F: ${expiresAtISO}`);
  }
  async getTrackedChatId(telegramId) {
    const user = await this.findOrCreateUser(telegramId);
    return user.trackedChatId;
  }
  async setTrackedChatId(telegramId, chatId) {
    await this.prisma.user.update({
      where: { telegramId },
      data: { trackedChatId: chatId }
    });
    this.logger.info(`\u0414\u043B\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F ${telegramId} (FREE) \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D \u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u0435\u043C\u044B\u0439 \u0447\u0430\u0442: ${chatId}`);
  }
}

// src/handlers/tribute-webhook.handler.ts
import crypto2 from "crypto";
class TributeWebhookHandler {
  subscriptionService;
  logger = Logger.getInstance();
  tributeApiKey;
  constructor(subscriptionService) {
    this.subscriptionService = subscriptionService;
    if (!process.env.TRIBUTE_API_KEY) {
      throw new Error("\u041F\u0435\u0440\u0435\u043C\u0435\u043D\u043D\u0430\u044F \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u044F TRIBUTE_API_KEY \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0430.");
    }
    this.tributeApiKey = process.env.TRIBUTE_API_KEY;
  }
  async handle(request2) {
    if (request2.method !== "POST") {
      return new Response("Method Not Allowed", { status: 405 });
    }
    const signature = request2.headers.get("trbt-signature");
    if (!signature) {
      this.logger.warn("Tribute Webhook: \u041E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043E\u043A trbt-signature");
      return new Response("Signature header is missing", { status: 400 });
    }
    const bodyText = await request2.text();
    const hmac2 = crypto2.createHmac("sha256", this.tributeApiKey);
    const digest = hmac2.update(bodyText).digest("hex");
    if (digest !== signature) {
      this.logger.warn("Tribute Webhook: \u041D\u0435\u0432\u0435\u0440\u043D\u0430\u044F \u043F\u043E\u0434\u043F\u0438\u0441\u044C");
      return new Response("Invalid signature", { status: 403 });
    }
    const payload = JSON.parse(bodyText);
    this.logger.info(`\u041F\u043E\u043B\u0443\u0447\u0435\u043D \u0432\u0435\u0431-\u0445\u0443\u043A \u043E\u0442 Tribute: ${payload.event} \u0434\u043B\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F ${payload.user.id}`);
    try {
      switch (payload.event) {
        case "new_subscription":
          await this.subscriptionService.setUserSubscriptionStatus(payload.user.id, "PREMIUM", payload.subscription.expires_at);
          break;
        case "cancelled_subscription":
          await this.subscriptionService.setUserSubscriptionStatus(payload.user.id, "FREE", null);
          break;
        default:
          this.logger.warn(`\u041D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u043E\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u0435 Tribute: ${payload.event}`);
      }
      return new Response("OK", { status: 200 });
    } catch (error) {
      this.logger.error("\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u0438 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0435 \u0432\u0435\u0431-\u0445\u0443\u043A\u0430 Tribute:", error);
      return new Response("Internal Server Error", { status: 500 });
    }
  }
}

