    this.subscriptionService = new SubscriptionService;
    try {
      this.s3Service = new S3Service(this.bot);
    } catch (error) {
      this.logger.warn("S3 Service \u043D\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D, \u0432\u044B\u0433\u0440\u0443\u0437\u043A\u0430 \u043C\u0435\u0434\u0438\u0430 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0430.");
      this.s3Service = undefined;
    }
