    this.messageEditHandler = new MessageEditHandler(this.cacheService, this.ownerId, telegramService);
    this.messageDeleteHandler = new MessageDeleteHandler(this.cacheService, this.ownerId, telegramService, this.s3Service);
    this.businessMessageHandler = new BusinessMessageHandler(this.cacheService, this.s3Service, this.subscriptionService);
    this.businessConnectionHandler = new BusinessConnectionHandler(this.ownerId);
    this.logger.info("TruthTellerBot \u0438\u043D\u0438\u0446\u0438\u0430\u043B\u0438\u0437\u0438\u0440\u043E\u0432\u0430\u043D");
    this.logger.info(`\u0412\u043B\u0430\u0434\u0435\u043B\u0435\u0446: ${this.ownerId}`);
